async def _run_routine(self, routine: api.models.CommandRoutine) -> None:
    routines = self._api_client.command_routine_execution_api

    async def start() -> api.models.CommandRoutineRun:
        with _unsupported_routine_command():
            return await routines.start_command_routine_run(
                cell=self._cell, command_routine=routine
            )

    # Shielded, so that a run starting while the call is cancelled is still stopped.
    starting = asyncio.ensure_future(start())
    try:
        run = await asyncio.shield(starting)
        while run.state not in _FINAL_ROUTINE_RUN_STATES:
            await asyncio.sleep(ROUTINE_RUN_POLL_INTERVAL_SECS)
            run = await routines.get_command_routine_run(cell=self._cell, run=run.run)
    except asyncio.CancelledError:
        run = await starting
        await routines.stop_command_routine_run(cell=self._cell, run=run.run)
        raise
    if run.state != api.models.CommandRoutineRunState.COMPLETED:
        raise RoutineRunFailed(run)

